#include <stdio.h>

/* teste do desafio cedo-demais — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A caixa do aluno e `void`: nao ha valor a conferir, so a SAIDA. A captura
   acontece DENTRO do teste (freopen + fflush, nunca fclose(stdout): cada
   cenario abre a sua propria captura e o stdout precisa ficar aberto). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void cedoDemais(int saldo);

/* cenario 1 — saldo positivo: as duas linhas, e a prova do FIM da saida */
SM_TEST(saldo_positivo_imprime_as_duas_linhas) {
    freopen("sm_saida_1.tmp", "w", stdout);
    cedoDemais(5);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do saldo", linha, "saldo: 5\n",
              "a primeira linha traz o saldo recebido");
    fgets(linha, 80, f);
    checa_str("a linha da liberacao", linha, "compra liberada\n",
              "a segunda linha e sempre a mesma");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

/* cenario 2 — outro saldo positivo: a primeira linha acompanha o valor */
SM_TEST(outro_saldo_muda_a_primeira_linha) {
    freopen("sm_saida_2.tmp", "w", stdout);
    cedoDemais(12);
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do saldo 12", linha, "saldo: 12\n",
              "o numero da linha vem do parametro, nao e um texto fixo");
    fgets(linha, 80, f);
    checa_str("a liberacao de novo", linha, "compra liberada\n",
              "a segunda linha nao depende do saldo");
    fclose(f);
}

/* cenario 3 — saldo negativo: a guarda sai antes e nada e impresso */
SM_TEST(saldo_negativo_nao_imprime_nada) {
    int negativo = 0 - 5;   /* um saldo negativo: cinco abaixo de zero */

    freopen("sm_saida_3.tmp", "w", stdout);
    cedoDemais(negativo);
    fflush(stdout);

    FILE *f = fopen("sm_saida_3.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("saldo negativo nao imprime", linha, "(nada impresso)",
              "a guarda encerra a caixa antes dos printf");
    fclose(f);
}

